'use strict';
(()=>{
const side=document.querySelector('aside nav'),anchor=[...side.querySelectorAll('button')].find(b=>b.textContent.trim()==='Репетиции');
const nav=document.createElement('button');nav.innerHTML='<svg class="icon" aria-hidden="true"><use href="icons.svg#rotate-ccw"></use></svg><span>Частота</span>';anchor.after(nav);
const page=document.createElement('main');page.id='frequency-page';page.hidden=true;
page.innerHTML=`<div class="breadcrumb">Коммуникации / Общая частота</div><div class="heading"><div><h1>Общий контроль частоты</h1><p>Один email — общая история рассылок и сценариев</p></div><button class="outline" id="fq-refresh">Обновить</button></div><div class="demo"><b>Только тестовый контур</b><span>Учитываются подготовленные письма репетиций и имитированные шаги сценариев. SMTP, рабочие контакты и очередь отправки не используются.</span></div><p role="status" id="fq-status"></p>
<section class="panel"><h2>Общие ограничения</h2><p id="fq-clock"></p><form id="fq-form"><label class="fq-toggle"><input id="fq-enabled" type="checkbox">Включить общий контроль</label><div class="fq-grid"><label>Минимальный интервал, минут<input id="fq-interval" type="number" min="1" max="10080" required></label><label>Писем за скользящие 24 часа, максимум<input id="fq-daily" type="number" min="1" max="100" required></label><label>Писем за скользящие 7 дней, максимум<input id="fq-weekly" type="number" min="1" max="500" required></label></div><button class="outline">Сохранить общие ограничения</button></form><p id="fq-policy-note"></p><p>Ключ клиента — email без пробелов по краям, без учёта регистра. Разные email одного человека считаются отдельно. Настройки сценария могут ограничивать частоту сильнее. Повтор того же письма после временной ошибки не добавляет новое письмо; его попытки ограничиваются отдельно.</p><p>При включённом контроле часы общие для сценариев и репетиций. Продвиньте время в одном из этих разделов, затем пересчитайте другой запуск. Его сохранённая дата показывает последний цикл обработки. Изменение политики перепроверяется при следующем цикле; история не сбрасывается, в том числе после отмены или ошибки.</p></section>
<section class="panel"><h2>История контактов</h2><p id="fq-total"></p><form id="fq-filters" class="fq-grid"><label>Email: поиск, для расчёта — точный адрес<input id="fq-query" type="search" maxlength="254"></label><label>Источник<select id="fq-source"><option value="">Все источники</option><option value="rehearsal">Репетиции</option><option value="scenario">Сценарии</option></select></label><label>Порядок<select id="fq-direction"><option value="desc">Сначала новые</option><option value="asc">Сначала старые</option></select></label><button class="outline">Применить фильтры</button></form><p id="fq-decision" role="status"></p><div id="fq-history" class="table-scroll"></div><div class="actions"><button class="outline" id="fq-prev">Назад</button><span id="fq-pagination"></span><button class="outline" id="fq-next">Далее</button></div></section><section class="panel"><h2>Изменения общих ограничений</h2><p>Последние 20 версий. Тестовая дата указана в общем часовом поясе.</p><div id="fq-changes" class="table-scroll"></div></section>`;
document.body.append(page);const $=id=>document.getElementById('fq-'+id);let data=null,busy=false,number=1,generation=0;
function text(tag,value){const el=document.createElement(tag);el.textContent=value??'';return el;}
function date(v){return new Date(v).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'});}
function table(host,headers,rows){const t=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');headers.forEach(h=>tr.append(text('th',h)));head.append(tr);t.append(head);const body=document.createElement('tbody');rows.forEach(values=>{const row=document.createElement('tr');values.forEach((v,i)=>{const td=text('td',v);td.dataset.label=headers[i];row.append(td);});body.append(row);});t.append(body);host.replaceChildren(t);if(!rows.length)host.append(text('p','Записей пока нет.'));}
function controls(){for(const el of page.querySelectorAll('input,select,button'))el.disabled=busy;$('form').querySelector('button').disabled=busy||!data;$('prev').disabled=busy||!data||number<=1;$('next').disabled=busy||!data||number>=data.pagination.pages;}
async function load(){const seq=++generation;const d=await api('/api/test-frequency?'+new URLSearchParams({query:$('query').value,source:$('source').value,direction:$('direction').value,page:String(number)}));if(seq!==generation)return;data=d;number=d.pagination.page;$('enabled').checked=d.policy.enabled;$('interval').value=d.policy.min_interval_minutes;$('daily').value=d.policy.max_24h;$('weekly').value=d.policy.max_7d;$('clock').textContent='Общее тестовое время: '+date(d.clock_at)+' (Asia/Qyzylorda)';$('policy-note').textContent=`${d.policy.enabled?'Общий контроль включён':'Общий контроль выключен'} · версия ${d.revision}. Учитываются все рассылки и сценарии; дубли одного письма и его повторы счётчик не увеличивают.`;$('total').textContent=`Тестовых контактов с email: ${d.total}; разных email: ${d.emails}. Отправок по SMTP: 0.`;
const decision=d.decision;$('decision').textContent=decision?(decision.enabled?`По точному email: за 24 часа ${decision.count_24h}, за 7 дней ${decision.count_7d}. ${decision.reasons.length?'Отложено: '+decision.reasons.join('; ')+'. Ближайший срок: '+date(decision.allowed_at):'Общий лимит сейчас не препятствует шагу; остальные условия проверяются отдельно.'}`:'Общий контроль выключен.'):'Для расчёта ближайшего срока введите точный email. Поиск истории допускает часть адреса.';
table($('history'),['Тестовое время','Email','Источник','Запуск','Сценарий','Рассылка'],d.history.map(r=>[date(r.at),r.email,r.source==='rehearsal'?'Репетиция':'Сценарий',r.run_id,r.scenario_id,r.campaign_id]));table($('changes'),['Версия','Тестовое время','Состояние','Интервал, мин','За 24 ч','За 7 дней'],d.changes.map(r=>[r.revision,date(r.clock_at),r.snapshot.enabled?'Включено':'Выключено',r.snapshot.min_interval_minutes,r.snapshot.max_24h,r.snapshot.max_7d]));$('pagination').textContent=`${number} / ${d.pagination.pages} · записей по фильтру: ${d.pagination.total}`;controls();}
async function mutate(fn){if(busy)return;busy=true;controls();$('status').textContent='';try{await fn();}catch(e){$('status').textContent=e.message;}finally{busy=false;controls();}}
$('form').onsubmit=e=>{e.preventDefault();mutate(async()=>{await api('/api/test-frequency',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'simulation',test_only:true,send:false,revision:data.revision,policy:{enabled:$('enabled').checked,min_interval_minutes:Number($('interval').value),max_24h:Number($('daily').value),max_7d:Number($('weekly').value)}})});await load();$('status').textContent='Общие ограничения сохранены. Следующие циклы перепроверят отложенные шаги.';});};$('refresh').onclick=()=>mutate(load);$('filters').onsubmit=e=>{e.preventDefault();number=1;mutate(load);};$('prev').onclick=()=>mutate(async()=>{number--;await load();});$('next').onclick=()=>mutate(async()=>{number++;await load();});
function open(){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;side.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===nav));sessionStorage.setItem('open-frequency','1');document.title='Общая частота';mutate(load);}
nav.onclick=open;side.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&b!==nav){page.hidden=true;generation++;sessionStorage.removeItem('open-frequency');}});
for(const id of ['automation-page','rehearsal-page']){const host=document.getElementById(id)?.querySelector('.heading');if(host){const b=text('button','Общий контроль частоты');b.className='outline';b.onclick=open;host.append(b);}}
if(sessionStorage.getItem('open-frequency'))open();
})();
